sql.content:
CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  email TEXT NOT NULL,
  created_at TEXT
);

hcl.content:
table "users" {
  column "id" {
    type = integer
    null = true
  }

  column "email" {
    type = text
    null = false
  }

  column "created_at" {
    type = text
    null = true
  }

  primary_key {
    columns = [column.id]
  }
}

dbml.content:
Table users {
  id integer [pk]
  email text [not null]
  created_at text
}

